#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Currency { Eur, Usd }

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub struct Money { cents: i64, currency: Currency }   // private fields

impl Money {
    pub fn cents(&self) -> i64 { self.cents }
    pub fn plus(&self, other: &Money) -> Money {
        Money { cents: self.cents + other.cents, ..*self }
    }
}

